import { readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';

const routeManifest = JSON.parse(await readFile(resolve('src/generated/sub2api-admin-routes.json'), 'utf8'));
const coreServiceSource = await readFile(resolve('src/services/admin.ts'), 'utf8');
const outputPath = resolve(process.argv[2] || 'src/services/official-admin.ts');

function findBalancedBlock(source, start) {
  let depth = 0;
  let quote = '';
  let escaped = false;
  for (let index = start; index < source.length; index += 1) {
    const char = source[index];
    if (quote) {
      if (escaped) escaped = false;
      else if (char === '\\') escaped = true;
      else if (char === quote) quote = '';
      continue;
    }
    if (char === "'" || char === '"' || char === '`') {
      quote = char;
      continue;
    }
    if (char === '{') depth += 1;
    if (char === '}' && --depth === 0) return source.slice(start, index + 1);
  }
  return source.slice(start);
}

function canonical(path) {
  return path
    .replace(/:buildQuery[\s\S]*$/, '')
    .replace(/\?.*$/, '')
    .replace(/:[^/]+/g, ':*')
    .replace(/\/$/, '');
}

const dedicatedKeys = new Set();
const functionPattern = /export function\s+\w+\s*\([\s\S]*?\)\s*\{/g;
for (const match of coreServiceSource.matchAll(functionPattern)) {
  const blockStart = match.index + match[0].lastIndexOf('{');
  const body = findBalancedBlock(coreServiceSource, blockStart);
  const method = body.match(/method:\s*['"]([A-Z]+)['"]/)?.[1] || 'GET';
  for (const endpoint of [...body.matchAll(/([`'"])([^`'"]*\/api\/v1\/admin[^`'"]*)\1/g)].map((item) => item[2])) {
    const normalized = endpoint.replace(/\$\{([^}]+)\}/g, ':$1');
    dedicatedKeys.add(`${method} ${canonical(normalized)}`);
  }
}

const missingRoutes = routeManifest.routes.filter((route) => (
  !dedicatedKeys.has(`${route.method} ${canonical(route.path)}`)
));
const usedNames = new Set();

function pascal(value) {
  return value
    .replace(/[^A-Za-z0-9]+(.)/g, (_, char) => char.toUpperCase())
    .replace(/^[a-z]/, (char) => char.toUpperCase())
    .replace(/[^A-Za-z0-9]/g, '');
}

function operationName(route) {
  const handlerParts = route.handler.split('.').filter(Boolean).slice(2);
  const base = `official${handlerParts.map(pascal).join('') || pascal(route.path)}`;
  let name = base;
  let suffix = 2;
  while (usedNames.has(name)) name = `${base}${pascal(route.method.toLowerCase())}${suffix++}`;
  usedNames.add(name);
  return name;
}

const operations = missingRoutes.map((route) => ({
  ...route,
  name: operationName(route),
  module: route.path.split('/')[4] || 'other',
  pathParams: [...route.path.matchAll(/:([A-Za-z_][A-Za-z0-9_]*)/g)].map((match) => match[1]),
  transport: route.path.includes('/ws/') ? 'websocket' : 'http',
}));

const header = `// This file is generated by .github/scripts/generate-official-admin-services.mjs.\n// It provides a stable callable wrapper for every official admin route that does not\n// already have a purpose-built implementation in src/services/admin.ts.\n\nimport { adminFetch, createAdminWebSocket } from '@/src/lib/admin-fetch';\n\nexport type OfficialAdminScalar = string | number | boolean;\nexport type OfficialAdminCallInput = {\n  path?: Record<string, OfficialAdminScalar>;\n  query?: Record<string, OfficialAdminScalar | readonly OfficialAdminScalar[] | null | undefined>;\n  body?: unknown;\n  headers?: Record<string, string>;\n};\n\nexport type OfficialAdminOperation = {\n  id: string;\n  name: string;\n  module: string;\n  method: string;\n  path: string;\n  handler: string;\n  pathParams: readonly string[];\n  transport: 'http' | 'websocket';\n};\n\nfunction resolveOfficialPath(path: string, values: Record<string, OfficialAdminScalar> = {}) {\n  return path.replace(/:([A-Za-z_][A-Za-z0-9_]*)/g, (_, name: string) => {\n    const value = values[name];\n    if (value === undefined || value === null || value === '') throw new Error(\`缺少路径参数：\${name}\`);\n    return encodeURIComponent(String(value));\n  });\n}\n\nfunction buildOfficialQuery(values: OfficialAdminCallInput['query']) {\n  const query = new URLSearchParams();\n  Object.entries(values || {}).forEach(([name, raw]) => {\n    if (raw === undefined || raw === null || raw === '') return;\n    const items = Array.isArray(raw) ? raw : [raw];\n    items.forEach((value) => query.append(name, String(value)));\n  });\n  const encoded = query.toString();\n  return encoded ? \`?\${encoded}\` : '';\n}\n\nexport function officialAdminRequest<T = unknown>(method: string, path: string, input: OfficialAdminCallInput = {}) {\n  const requestPath = \`\${resolveOfficialPath(path, input.path)}\${buildOfficialQuery(input.query)}\`;\n  const init: RequestInit = { method, headers: input.headers };\n  if (input.body !== undefined) init.body = typeof input.body === 'string' ? input.body : JSON.stringify(input.body);\n  return adminFetch<T>(requestPath, init);\n}\n\nexport function officialAdminWebSocket(path: string, input: OfficialAdminCallInput = {}) {\n  return createAdminWebSocket(\`\${resolveOfficialPath(path, input.path)}\${buildOfficialQuery(input.query)}\`);\n}\n\n`;

const registry = `export const officialAdminOperations: readonly OfficialAdminOperation[] = ${JSON.stringify(operations.map((operation) => ({
  id: `${operation.method} ${operation.path}`,
  name: operation.name,
  module: operation.module,
  method: operation.method,
  path: operation.path,
  handler: operation.handler,
  pathParams: operation.pathParams,
  transport: operation.transport,
})), null, 2)} as const;\n\n`;

const wrappers = operations.map((operation) => (
  operation.transport === 'websocket'
    ? `export function ${operation.name}(input: OfficialAdminCallInput = {}) {\n  return officialAdminWebSocket('${operation.path}', input);\n}`
    : `export function ${operation.name}(input: OfficialAdminCallInput = {}) {\n  return officialAdminRequest<unknown>('${operation.method}', '${operation.path}', input);\n}`
)).join('\n\n');

await writeFile(outputPath, `${header}${registry}${wrappers}\n`, 'utf8');
console.log(`Wrote ${operations.length} official admin route wrappers to ${outputPath}`);
